function Products({ onOpenSchedule }: { onOpenSchedule: (productId: string) => void }) {
    const queryClient = useQueryClient(); const { data: products = [] } = useQuery({ queryKey: ["admin-products"], queryFn: fetchAllProducts }); const { data: categories = [] } = useQuery({ queryKey: ["categories"], queryFn: fetchCategories }); const [adding, setAdding] = useState(false); const [editing, setEditing] = useState<Product | null>(null); const [expanded, setExpanded] = useState<string | null>(null); const [skuProduct, setSkuProduct] = useState<Product | null>(null);
    const { data: skus = [], error: skuLoadError } = useQuery({
        queryKey: ["admin-skus"],
        queryFn: async () => {
            const { data, error } = await supabase.from("product_skus").select("*").order("created_at");
            if (error) throw error;
            return data ?? [];
        },
    });
    const refresh = () => queryClient.invalidateQueries({ queryKey: ["admin-products"] });
    async function toggle(product: Product) { const { error } = await supabase.from("products").update({ status: !product.status }).eq("id", product.id); if (error) window.alert(error.message); else refresh(); }
    function addSku(product: Product) { setSkuProduct(product); }
    const [deleteTarget, setDeleteTarget] = useState<Product | null>(null);
    const [deleting, setDeleting] = useState(false);
    const [deleteError, setDeleteError] = useState("");
    async function confirmDelete() {
        if (!deleteTarget || deleting) return;
        const id = deleteTarget.id;
        setDeleting(true); setDeleteError("");
        const controller = new AbortController();
        let timeout: ReturnType<typeof setTimeout> | undefined;
        try {
            const request = supabase.from("products").delete().eq("id", id).select("id").abortSignal(controller.signal);
            const deadline = new Promise<never>((_, reject) => {
                timeout = setTimeout(() => {
                    controller.abort();
                    reject(new Error("Koneksi terlalu lama. Status penghapusan belum dapat dipastikan. Muat ulang daftar sebelum mencoba lagi."));
                }, 15000);
            });
            const { data, error } = await Promise.race([request, deadline]);
            if (error) {
                if (error.code === "23503") throw new Error("Barang masih terkait jadwal sewa sehingga tidak dapat dihapus. Nonaktifkan barang jika tidak ingin ditampilkan di katalog.");
                if (error.code === "42501") throw new Error("Akun tidak memiliki izin menghapus barang. Silakan masuk kembali dengan akun admin.");
                throw new Error(error.message || "Supabase tidak dapat memproses penghapusan. Periksa koneksi dan coba lagi.");
            }
            if (!data?.length) throw new Error("Barang tidak ditemukan atau akun tidak memiliki akses untuk menghapusnya. Muat ulang daftar dan periksa akses admin.");
            queryClient.setQueryData<Product[]>(["admin-products"], current => current?.filter(product => product.id !== id));
            queryClient.setQueryData<Product[]>(["public-products"], current => current?.filter(product => product.id !== id));
            setDeleteTarget(null);
            void refresh();
            void queryClient.invalidateQueries({ queryKey: ["public-products"] });
        } catch (error) {
            setDeleteError(error instanceof Error ? error.message : "Gagal menghapus barang. Silakan coba lagi.");
            void refresh();
        } finally {
            if (timeout) clearTimeout(timeout);
            setDeleting(false);
        }
    }

    return <><section className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/20"><div className="flex items-center justify-between border-b border-slate-800 p-6"><div><h2 className="font-bold">Barang Sewaan</h2><p className="mt-1 text-sm text-slate-500">{products.length} barang di katalog.</p></div><button type="button" onClick={() => setAdding(true)} className="rounded-xl bg-blue-500 px-4 py-3 text-sm font-bold"><Plus size={16} className="mr-1 inline" /> Tambah barang</button></div><div className="divide-y divide-slate-800">{products.map((product) => <article key={product.id}><div className="flex flex-wrap items-center gap-3 p-5"><div className="min-w-[12rem] flex-1"><div className="flex gap-2"><h3 className="font-bold">{product.name}</h3><span className={`rounded-full px-2 py-1 text-[.6rem] font-bold ${product.status ? "bg-emerald-500/15 text-emerald-400" : "bg-slate-800 text-slate-400"}`}>{product.status ? "TAMPIL" : "NONAKTIF"}</span></div><p className="mt-1 text-xs text-blue-300">{categories.find((c) => c.id === product.category_id)?.name ?? "Koleksi"} · {formatRupiah(product.price)}/3 hari</p></div><button type="button" onClick={() => setExpanded(expanded === product.id ? null : product.id)} className="rounded-xl border border-blue-400/40 px-3 py-2 text-xs text-blue-300">{skus.filter(item => item.product_id === product.id).length} SKU <ChevronDown size={14} className="ml-1 inline" /></button><button type="button" onClick={() => toggle(product)} className={`rounded-xl px-3 py-2 text-xs font-bold ${product.status ? "bg-blue-500" : "bg-slate-700"}`}>{product.status ? "Tampil" : "Aktifkan"}</button><button type="button" onClick={() => onOpenSchedule(product.id)} className="inline-flex items-center gap-2 rounded-xl border border-slate-800 px-3 py-2 text-xs font-bold"><CalendarDays size={16} aria-hidden="true" /> Jadwal</button><button type="button" onClick={() => setEditing(product)} className="inline-flex items-center gap-2 rounded-xl border border-slate-800 px-3 py-2 text-xs font-bold"><Pencil size={16} aria-hidden="true" /> Edit</button><button type="button" aria-label={`Hapus ${product.name}`} onClick={() => { setDeleteError(""); setDeleteTarget(product); }} className="rounded-xl border border-rose-500/40 p-2 text-rose-400"><Trash2 size={16} /></button></div>{expanded === product.id && <div className="mx-5 mb-5 border-l-2 border-blue-500 pl-5"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase">SKU / Unit sewaan</p><p className="mt-1 text-xs text-slate-500">Jadwal setiap unit dapat dipisahkan.</p></div><button type="button" onClick={() => addSku(product)} className="rounded-lg bg-slate-700 px-3 py-2 text-xs font-bold"><Plus size={14} className="mr-1 inline" /> Tambah SKU</button></div><div className="mt-3 space-y-2">
{skuLoadError && <p role="alert" className="text-sm text-rose-400">SKU gagal dimuat: {skuLoadError.message}</p>}
{skus.filter(item => item.product_id === product.id).map(item => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-slate-800 p-3 text-sm"><div><b>{item.name}</b><p className="mt-1 text-xs text-slate-400">{item.sku} · Stok {item.stock} · {item.status ? "Aktif" : "Nonaktif"}</p></div><span>{formatRupiah(item.price ?? product.price)}</span></div>)}
{!skuLoadError && !skus.some(item => item.product_id === product.id) && <p className="text-sm text-slate-400">Belum ada SKU. Klik Tambah SKU untuk menambahkan varian.</p>}
</div></div>}</article>)}</div></section>{adding && <AddProductPanel categories={categories} onClose={() => setAdding(false)} />}{editing && <EditProductPanel product={editing} categories={categories} onClose={() => setEditing(null)} />}{skuProduct && <AddSkuPanel product={skuProduct} onClose={() => { setExpanded(skuProduct.id); setSkuProduct(null); }} />}<AlertDialog open={Boolean(deleteTarget)} onOpenChange={open => { if (!open && !deleting) setDeleteTarget(null); }}><AlertDialogContent className="max-w-[calc(100%-2rem)] rounded-xl border-slate-700 bg-[#0d1016] text-white sm:max-w-md"><AlertDialogHeader><AlertDialogTitle>Hapus barang?</AlertDialogTitle><AlertDialogDescription className="text-slate-400">Apakah Anda ingin menghapus barang <strong className="text-white">{deleteTarget?.name}</strong>?</AlertDialogDescription></AlertDialogHeader>{deleteError && <p role="alert" className="text-sm text-rose-400">{deleteError}</p>}<AlertDialogFooter><AlertDialogCancel disabled={deleting} className="rounded-lg border-slate-700 bg-transparent text-white hover:bg-slate-800 hover:text-white">Tidak</AlertDialogCancel><AlertDialogAction disabled={deleting} onClick={event => { event.preventDefault(); void confirmDelete(); }} className="rounded-lg bg-rose-600 text-white hover:bg-rose-500 disabled:opacity-50">{deleting ? "Menghapus..." : "Ya, hapus"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function ProductsWithSkuModal({ onOpenSchedule }: { onOpenSchedule: (productId: string) => void }) {
    const queryClient = useQueryClient(); const { data: products = [] } = useQuery({ queryKey: ["admin-products"], queryFn: fetchAllProducts }); const { data: categories = [] } = useQuery({ queryKey: ["categories"], queryFn: fetchCategories }); const [adding, setAdding] = useState(false); const [editing, setEditing] = useState<Product | null>(null); const [skuProduct, setSkuProduct] = useState<Product | null>(null);
    async function toggle(product: Product) { const { error } = await supabase.from("products").update({ status: !product.status }).eq("id", product.id); if (error) window.alert(error.message); else queryClient.invalidateQueries({ queryKey: ["admin-products"] }); }
    async function remove(product: Product) { if (!window.confirm(`Hapus ${product.name}?`)) return; const { error } = await supabase.from("products").delete().eq("id", product.id); if (error) window.alert(error.message); else queryClient.invalidateQueries({ queryKey: ["admin-products"] }); }
    return <><section className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/20"><div className="flex items-center justify-between border-b border-slate-800 p-6"><div><h2 className="font-bold">Barang Sewaan</h2><p className="mt-1 text-sm text-slate-500">{products.length} barang di katalog.</p></div><button type="button" onClick={() => setAdding(true)} className="rounded-xl bg-blue-500 px-4 py-3 text-sm font-bold"><Plus size={16} className="mr-1 inline" /> Tambah barang</button></div><div className="divide-y divide-slate-800">{products.map((product) => <div key={product.id} className="flex flex-wrap items-center gap-3 p-5"><div className="min-w-[12rem] flex-1"><div className="flex gap-2"><b>{product.name}</b><span className={`rounded-full px-2 py-1 text-[.6rem] ${product.status ? "bg-emerald-500/15 text-emerald-400" : "bg-slate-800 text-slate-400"}`}>{product.status ? "TAMPIL" : "NONAKTIF"}</span></div><p className="mt-1 text-xs text-blue-300">{formatRupiah(product.price)}/3 hari</p></div><button type="button" onClick={() => setSkuProduct(product)} className="rounded-xl border border-blue-400/40 px-3 py-2 text-xs text-blue-300">SKU <Plus size={13} className="ml-1 inline" /></button><button type="button" onClick={() => toggle(product)} className="rounded-xl bg-blue-500 px-3 py-2 text-xs">{product.status ? "Tampil" : "Aktifkan"}</button><button type="button" onClick={() => onOpenSchedule(product.id)} className="rounded-xl border border-slate-800 px-3 py-2 text-xs">Jadwal</button><button type="button" onClick={() => setEditing(product)} className="rounded-xl border border-slate-800 p-2"><Pencil size={16} /></button><button type="button" onClick={() => remove(product)} className="rounded-xl border border-rose-500/40 p-2 text-rose-400"><Trash2 size={16} /></button></div>)}</div></section>{adding && <AddProductPanel categories={categories} onClose={() => setAdding(false)} />}{editing && <EditProductPanel product={editing} categories={categories} onClose={() => setEditing(null)} />}{skuProduct && <AddSkuPanel product={skuProduct} onClose={() => setSkuProduct(null)} />}</>;
}

function AddSkuPanel({ product, onClose }: { product: Product; onClose: () => void }) {
    const queryClient = useQueryClient(); const [file, setFile] = useState<File | null>(null); const [name, setName] = useState(""); const [sku, setSku] = useState(""); const [label, setLabel] = useState(""); const [stock, setStock] = useState("1"); const [size, setSize] = useState(""); const [colour, setColour] = useState(""); const [bestRental, setBestRental] = useState(""); const [description, setDescription] = useState(""); const [price, setPrice] = useState(""); const [active, setActive] = useState(true); const [message, setMessage] = useState("");
    const [saving, setSaving] = useState(false);
    async function save(event: React.FormEvent) { event.preventDefault(); if (saving) return; setSaving(true); setMessage(""); try { const image_url = file ? await uploadProductImage(file) : null; const { error } = await supabase.from("product_skus").insert({ product_id: product.id, sku: sku.trim() || `${product.slug.toUpperCase()}-${crypto.randomUUID()}`, name: name || "Varian 1", image_url, price: price ? Number(price) : null, stock: Number(stock) || 1, status: active }); if (error) throw new Error(error.message); await queryClient.invalidateQueries({ queryKey: ["admin-skus"] }); await queryClient.invalidateQueries({ queryKey: ["public-skus"] }); onClose(); } catch (error) { setMessage(error instanceof Error ? error.message : "SKU tidak dapat disimpan."); } finally { setSaving(false); } }
    return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><form onSubmit={save} className="max-h-[92vh] w-full max-w-5xl overflow-y-auto rounded-2xl border border-slate-700 bg-[#0b0d12] text-slate-100 shadow-2xl"><header className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-800 bg-[#0b0d12] px-6 py-5"><div><h2 className="font-bold">Tambah SKU · {product.name}</h2><p className="mt-1 text-sm text-slate-400">Harga, foto, dan deskripsi kosong mengikuti produk induk.</p></div><button type="button" onClick={onClose} className="rounded-lg border border-slate-800 p-2"><X size={18} /></button></header><div className="grid gap-6 p-6 lg:grid-cols-[12rem_1fr]"><section className="h-fit rounded-xl border border-slate-800 p-4"><h3 className="font-bold">Foto SKU</h3><label className="mt-4 grid aspect-[4/5] cursor-pointer place-items-center border border-dashed border-slate-700 text-center text-xs text-slate-500">{file ? <img src={URL.createObjectURL(file)} alt="SKU" className="h-full w-full object-cover" /> : <>Tambah foto<br />1/1</>}<FileUploadButton className="hidden" accept="image/*" onChange={(e) => setFile(e.target.files?.[0] ?? null)} /></label></section><div className="space-y-5"><button disabled={saving} className="h-12 w-full rounded-xl bg-emerald-600 text-sm font-bold disabled:opacity-50">{saving ? "Menyimpan..." : "Tambah SKU"}</button><label className="block rounded-xl border border-slate-800 p-4 text-sm"><input type="checkbox" checked={active} onChange={(e) => setActive(e.target.checked)} /> <span className="ml-2 font-bold">SKU aktif</span><p className="ml-6 mt-1 text-xs text-slate-500">Matikan jika sedang rusak.</p></label><section className="rounded-xl border border-slate-800 p-5"><h3 className="font-bold">Informasi SKU</h3><div className="mt-5 grid gap-4 md:grid-cols-3"><Field label="Nama SKU"><input className={inputClass} value={name} onChange={(e) => setName(e.target.value)} placeholder="Contoh: Unit A" /></Field><Field label="Kode SKU"><input className={inputClass} value={sku} onChange={(e) => setSku(e.target.value)} placeholder="Contoh: KEB-001" /></Field><Field label="Tag / label"><input className={inputClass} value={label} onChange={(e) => setLabel(e.target.value)} /></Field></div><div className="mt-5 grid gap-4 rounded-xl border border-slate-800 p-4 md:grid-cols-2"><Field label="Jumlah stok SKU"><input className={inputClass} type="number" min="1" value={stock} onChange={(e) => setStock(e.target.value)} /></Field><Field label="Ukuran"><input className={inputClass} value={size} onChange={(e) => setSize(e.target.value)} /></Field><Field label="Warna"><input className={inputClass} value={colour} onChange={(e) => setColour(e.target.value)} /></Field><Field label="Best rental"><input className={inputClass} value={bestRental} onChange={(e) => setBestRental(e.target.value)} /></Field></div><div className="mt-5 grid gap-4 md:grid-cols-2"><Field label="Deskripsi khusus"><textarea className="mt-2 min-h-32 w-full border border-slate-700 bg-slate-950 p-3 text-sm" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Kosongkan untuk mengikuti produk induk." /></Field><Field label="Override harga"><RupiahInput className={inputClass} value={price} onValueChange={(value) => setPrice(value)} placeholder="Kosongkan untuk harga induk" /></Field></div></section>{message && <p className="text-sm text-rose-400">{message}</p>}</div></div></form></div>;
}

function AddProductPanel({ categories, onClose }: { categories: { id: string; name: string }[]; onClose: () => void }) {
    const queryClient = useQueryClient(); const [files, setFiles] = useState<File[]>([]); const [name, setName] = useState(""); const [categoryId, setCategoryId] = useState(""); const [description, setDescription] = useState(""); const [price, setPrice] = useState(""); const [sku, setSku] = useState(""); const [stock, setStock] = useState("1"); const [size, setSize] = useState(""); const [colour, setColour] = useState(""); const [days, setDays] = useState("3"); const [worth, setWorth] = useState(""); const [deposit, setDeposit] = useState(""); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
    const validAmount = (value: string) => value === "" || (Number.isFinite(Number(value)) && Number(value) >= 0);
    const canSave = Boolean(name.trim() && price.trim()) && validAmount(price) && validAmount(worth) && validAmount(deposit)
        && Number.isInteger(Number(days)) && Number(days) >= 1 && Number.isInteger(Number(stock)) && Number(stock) >= 1;
    const progress = useRef<{ id?: string; paths?: string[]; gallery: boolean; sku: boolean }>({ gallery: false, sku: false });
    async function save(event: React.FormEvent) {
        event.preventDefault();
        if (!canSave || saving) return;
        setSaving(true); setMessage("");
        try {
            const draft = progress.current;
            const paths = draft.paths ?? await Promise.all(files.map(uploadProductImage));
            draft.paths = paths;
            const payload = { name: name.trim(), category_id: categoryId || null, description: description || null,
                main_image: paths[0] ?? null, price: Number(price), minimum_rental_days: Number(days),
                rental_worth: worth ? Number(worth) : null, deposit: deposit ? Number(deposit) : null };
            if (!draft.id) {
                const { data, error } = await supabase.from("products").insert({
                    ...payload, slug: slugify(name) + "-" + crypto.randomUUID(),
                }).select("id").single();
                if (error || !data) throw new Error(error?.message ?? "Barang tidak dapat disimpan.");
                draft.id = data.id;
            }
            if (!draft.gallery && paths.length > 1) {
                const { error } = await supabase.from("product_images").insert(paths.slice(1).map(image_url => ({ product_id: draft.id!, image_url })));
                if (error) throw new Error("Galeri belum tersimpan: " + error.message + ". Klik Simpan untuk mencoba kembali.");
                draft.gallery = true;
            }
            if (!draft.sku && sku.trim()) {
                const { error } = await supabase.from("product_skus").insert({ product_id: draft.id,
                    sku: sku.trim(), name: "Varian 1", price: Number(price), stock: Number(stock) });
                if (error) throw new Error("SKU belum tersimpan: " + error.message + ". Klik Simpan untuk mencoba kembali.");
                draft.sku = true;
            }
            for (const key of ["admin-products", "admin-skus", "public-products"]) void queryClient.invalidateQueries({ queryKey: [key] });
            onClose();
        } catch (error) {
            setMessage(error instanceof Error ? error.message : "Barang tidak dapat disimpan.");
            void queryClient.invalidateQueries({ queryKey: ["admin-products"] });
        } finally { setSaving(false); }
    }
    return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><form onSubmit={save} className="max-h-[92vh] w-full max-w-6xl overflow-y-auto rounded-2xl border border-slate-700 bg-[#0b0d12] text-slate-100 shadow-2xl"><header className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-800 bg-[#0b0d12] px-6 py-5"><div><h2 className="font-bold">Tambah barang</h2><p className="mt-1 text-sm text-slate-400">Isi nama, harga, deskripsi, dan upload sampai 3 foto.</p></div><button type="button" onClick={onClose} className="rounded-lg border border-slate-800 p-2"><X size={18} /></button></header><div className="grid gap-6 p-6 lg:grid-cols-[1fr_15rem]"><div className="space-y-6"><ProductPhotoPicker files={files} onChange={next => { delete progress.current.paths; setFiles(next); }} disabled={saving || Boolean(progress.current.id)} /><section className="rounded-2xl border border-slate-800 p-5"><h3 className="font-bold">Informasi Produk</h3><div className="mt-5 grid gap-5 md:grid-cols-2"><Field label="Nama barang"><input className={inputClass} value={name} onChange={(e) => setName(e.target.value)} required /></Field><div><Field label="Kategori"><select className={inputClass} value={categoryId} onChange={(e) => setCategoryId(e.target.value)}><option value="">Pilih kategori</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><div className="mt-3"><CategoryManager onCreated={setCategoryId} /></div></div><Field label="Deskripsi"><textarea className="mt-2 min-h-36 w-full border border-slate-700 bg-slate-950 p-3 text-sm" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Jelaskan kondisi, ukuran, dan info penting." /></Field><div className="grid grid-cols-2 gap-3"><Field label="Jumlah stok"><input className={inputClass} type="number" min="1" value={stock} onChange={(e) => setStock(e.target.value)} /></Field><Field label="Ukuran"><input className={inputClass} value={size} onChange={(e) => setSize(e.target.value)} placeholder="Contoh: M" /></Field><Field label="Warna"><input className={inputClass} value={colour} onChange={(e) => setColour(e.target.value)} placeholder="Contoh: Maroon" /></Field><Field label="Kode SKU"><input className={inputClass} value={sku} onChange={(e) => setSku(e.target.value)} placeholder="Contoh: KEB-001" /></Field></div></div></section><section className="rounded-2xl border border-slate-800 p-5"><div className="grid gap-5 md:grid-cols-2"><div><h3 className="font-bold">Harga sewa</h3><Field label="Harga paket"><RupiahInput className={inputClass} value={price} onValueChange={(value) => setPrice(value)} required /></Field><Field label="Durasi sewa (hari)"><input className={inputClass} type="number" min="1" value={days} onChange={(e) => setDays(e.target.value)} /></Field></div><div><h3 className="font-bold">Informasi tambahan</h3><Field label="Harga retail / worth"><RupiahInput className={inputClass} value={worth} onValueChange={(value) => setWorth(value)} /></Field><Field label="Uang jaminan / deposit"><RupiahInput className={inputClass} value={deposit} onValueChange={(value) => setDeposit(value)} /></Field></div></div></section></div><aside className="h-fit space-y-4"><button disabled={!canSave || saving} className={`h-12 w-full rounded-xl text-sm font-bold text-white transition-colors disabled:cursor-not-allowed ${canSave && !saving ? "bg-emerald-600 hover:bg-emerald-500" : "bg-slate-600"}`}>{saving ? "Menyimpan…" : "Simpan barang"}</button>{message && <p className="text-sm text-rose-400">{message}</p>}<label className="block rounded-xl border border-slate-800 p-4 text-sm"><input type="checkbox" defaultChecked /> <span className="ml-2 font-bold">Tampilkan di katalog</span></label><label className="block rounded-xl border border-slate-800 p-4 text-sm"><input type="checkbox" defaultChecked /> <span className="ml-2 font-bold">Produk memiliki beberapa SKU</span></label></aside></div></form></div>;
}

function EditProductPanel({ product, categories, onClose }: { product: Product; categories: { id: string; name: string }[]; onClose: () => void }) {
    const queryClient = useQueryClient();
    const [form, setForm] = useState({ name: product.name, category_id: product.category_id ?? "", description: product.description ?? "", price: String(product.price), status: product.status, pinned: product.pinned ?? false, has_multiple_skus: product.has_multiple_skus ?? true, minimum_rental_days: String(product.minimum_rental_days ?? 3), rental_worth: String(product.rental_worth ?? ""), deposit: String(product.deposit ?? "") });
    const [message, setMessage] = useState("");
    const change = (key: keyof typeof form, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }));
    async function save() { const { error } = await supabase.from("products").update({ name: form.name, category_id: form.category_id || null, description: form.description || null, price: Number(form.price) || 0, status: form.status, pinned: form.pinned, has_multiple_skus: form.has_multiple_skus, minimum_rental_days: Number(form.minimum_rental_days) || 3, rental_worth: form.rental_worth ? Number(form.rental_worth) : null, deposit: form.deposit ? Number(form.deposit) : null }).eq("id", product.id); if (error) { setMessage(error.message); return; } queryClient.invalidateQueries({ queryKey: ["admin-products"] }); onClose(); }
    return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#0b0d12] text-slate-100"><header className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-800 bg-[#0b0d12] px-6 py-5"><div><h2 className="font-bold">Edit barang</h2><p className="mt-1 text-sm text-slate-400">Ubah nama, status, harga, deskripsi, atau galeri foto.</p></div><button type="button" onClick={onClose} className="rounded-lg border border-slate-800 p-2"><X size={18} /></button></header><div className="mx-auto grid max-w-6xl gap-6 p-6 lg:grid-cols-[1fr_17rem]"><div className="space-y-6"><section className="rounded-2xl border border-slate-800 p-5"><h3 className="font-bold">Foto produk</h3><p className="mt-1 text-xs text-slate-500">Foto pertama menjadi cover. Upload galeri dapat ditambahkan setelah produk disimpan.</p><div className="mt-4 grid grid-cols-3 gap-3"><div className="grid aspect-[4/5] place-items-center rounded-lg bg-slate-800 text-xs text-slate-500">Foto cover produk</div><div className="grid place-items-center rounded-lg border border-dashed border-slate-700 text-xs text-slate-500">Foto tambahan</div><div className="grid place-items-center rounded-lg border border-dashed border-slate-700 text-xs text-slate-500">Foto tambahan</div></div></section><section className="rounded-2xl border border-slate-800 p-5"><h3 className="font-bold">Informasi produk</h3><div className="mt-5 grid gap-5 md:grid-cols-2"><Field label="Nama barang"><input className={inputClass} value={form.name} onChange={(e) => change("name", e.target.value)} /></Field><Field label="Kategori"><select className={inputClass} value={form.category_id} onChange={(e) => change("category_id", e.target.value)}><option value="">Pilih kategori</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><Field label="Deskripsi"><textarea className="mt-2 min-h-40 w-full border border-slate-700 bg-slate-950 p-3 text-sm" value={form.description} onChange={(e) => change("description", e.target.value)} /></Field><div><Field label="Harga sewa"><RupiahInput className={inputClass} value={form.price} onValueChange={(value) => change("price", value)} /></Field><Field label="Minimum durasi sewa (hari)"><input className={inputClass} type="number" min="1" value={form.minimum_rental_days} onChange={(e) => change("minimum_rental_days", e.target.value)} /></Field></div></div></section><section className="rounded-2xl border border-slate-800 p-5"><h3 className="font-bold">Informasi tambahan</h3><div className="mt-5 grid gap-5 md:grid-cols-2"><Field label="Harga retail / worth"><RupiahInput className={inputClass} value={form.rental_worth} onValueChange={(value) => change("rental_worth", value)} /></Field><Field label="Uang jaminan / deposit"><RupiahInput className={inputClass} value={form.deposit} onValueChange={(value) => change("deposit", value)} /></Field></div></section></div><aside className="h-fit space-y-4 lg:sticky lg:top-24"><button type="button" onClick={save} className="h-12 w-full rounded-xl bg-slate-600 text-sm font-bold">Simpan perubahan</button>{message && <p className="text-sm text-rose-400">{message}</p>}<label className="block rounded-xl border border-slate-800 p-4 text-sm"><input type="checkbox" checked={form.status} onChange={(e) => change("status", e.target.checked)} /> <span className="ml-2 font-bold">Tampilkan di katalog</span><p className="ml-6 mt-1 text-xs text-slate-500">Matikan jika belum siap.</p></label><label className="block rounded-xl border border-slate-800 p-4 text-sm"><input type="checkbox" checked={form.pinned} onChange={(e) => change("pinned", e.target.checked)} /> <span className="ml-2 font-bold">Sematkan di atas</span></label><label className="block rounded-xl border border-slate-800 p-4 text-sm"><input type="checkbox" checked={form.has_multiple_skus} onChange={(e) => change("has_multiple_skus", e.target.checked)} /> <span className="ml-2 font-bold">Produk memiliki beberapa SKU</span></label></aside></div></div>;
}

function LegacySchedules({ selectedProductId }: { selectedProductId: string | null }) {
    const { data: bookings = [], isLoading } = useQuery({ queryKey: ["bookings"], queryFn: async () => { const { data, error } = await supabase.from("bookings").select("*").order("start_date"); if (error) throw error; return data; } });
    const { data: items = [] } = useQuery({ queryKey: ["booking-items"], queryFn: async () => { const { data, error } = await supabase.from("booking_items").select("*"); if (error) throw error; return data; } });
    const { data: products = [] } = useQuery({ queryKey: ["admin-products"], queryFn: fetchAllProducts });
    const filtered = selectedProductId ? bookings.filter((booking) => items.some((item) => item.booking_id === booking.id && item.product_id === selectedProductId)) : bookings;
    return <section className="rounded-2xl border border-slate-800 bg-slate-900/20"><div className="border-b border-slate-800 p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="font-bold">Jadwal Sewa</h2><p className="mt-1 text-sm text-slate-500">Catat booking supaya tanggalnya otomatis tertutup di katalog.</p></div><button type="button" className="inline-flex items-center gap-2 rounded-xl bg-blue-500 px-4 py-3 text-sm font-bold"><Plus size={16} /> Tambah jadwal</button></div><div className="mt-6 flex flex-wrap gap-2"><button className="rounded-full bg-slate-700 px-4 py-2 text-xs font-bold">Semua</button><button className="rounded-full border border-slate-800 px-4 py-2 text-xs">Hari ini</button><button className="rounded-full border border-slate-800 px-4 py-2 text-xs">7 hari</button>{selectedProductId && <span className="rounded-full border border-blue-400/40 px-4 py-2 text-xs text-blue-300">Barang dipilih</span>}</div></div>{isLoading ? <p className="p-10 text-center text-sm text-slate-500">Memuat jadwal…</p> : filtered.length === 0 ? <div className="grid min-h-80 place-items-center text-center"><div><CalendarDays className="mx-auto text-slate-600" size={34} /><p className="mt-5 font-bold">Tidak ada jadwal yang cocok</p><p className="mt-2 text-sm text-slate-500">Buat booking baru atau ganti filter.</p></div></div> : <div className="divide-y divide-slate-800">{filtered.map((booking) => { const item = items.find((entry) => entry.booking_id === booking.id); const product = products.find((entry) => entry.id === item?.product_id); return <article key={booking.id} className="flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="font-bold">{product?.name ?? "Barang sewaan"}</p><p className="mt-1 text-sm text-slate-400">{booking.customer_name} · {booking.customer_whatsapp}</p></div><div className="text-sm"><p>{booking.start_date} — {booking.end_date}</p><span className="text-xs text-amber-400">{booking.status}</span></div></article>; })}</div>}</section>;
}

function LegacyScheduleList({ selectedProductId }: { selectedProductId: string | null }) {
    const { data: products = [] } = useQuery({ queryKey: ["admin-products"], queryFn: fetchAllProducts });
    const { data: bookings = [], isLoading } = useQuery({ queryKey: ["bookings"], queryFn: async () => { const { data, error } = await supabase.from("bookings").select("*").order("created_at", { ascending: false }); if (error) throw error; return data; } });
    const [search, setSearch] = useState(""); const [period, setPeriod] = useState("Semua"); const [view, setView] = useState("List"); const [productId, setProductId] = useState(selectedProductId ?? "");
    const shown = bookings.filter((booking) => booking.customer_name.toLowerCase().includes(search.toLowerCase()) || booking.customer_whatsapp.includes(search));
    return <section className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/20"><div className="border-b border-slate-800 p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="font-bold">Jadwal Sewa</h2><p className="mt-1 text-xs text-slate-400">Catat booking supaya tanggalnya otomatis tertutup di katalog.</p></div><button type="button" className="rounded-lg bg-blue-500 px-4 py-2 text-xs font-bold"><Plus size={14} className="mr-1 inline" /> Tambah jadwal</button></div></div><div className="border-b border-slate-800 px-5 py-4"><div className="flex flex-wrap items-center gap-2"><span className="mr-1 text-xs text-slate-500">Waktu:</span>{["Semua", "Hari ini", "7 hari", "Terlambat"].map((item) => <button key={item} type="button" onClick={() => setPeriod(item)} className={`rounded-full px-3 py-2 text-[.65rem] font-bold ${period === item ? "bg-slate-700 text-white" : "border border-slate-800 text-slate-400"}`}>{item}</button>)}</div></div><div className="flex flex-wrap gap-2 border-b border-slate-800 p-4"><input className="h-10 min-w-44 flex-1 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs outline-none focus:border-blue-400" placeholder="Cari barang, customer, atau WA..." value={search} onChange={(event) => setSearch(event.target.value)} /><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs" value={productId} onChange={(event) => setProductId(event.target.value)}><option value="">Semua barang</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs"><option>Semua SKU</option></select><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs"><option>Status aktif</option><option>Pending</option><option>Terkonfirmasi</option></select><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs"><option>Terakhir dibuat</option></select><div className="flex rounded-lg border border-slate-800 p-1 text-xs"><button type="button" onClick={() => setView("List")} className={`rounded px-3 py-1.5 ${view === "List" ? "bg-slate-700" : "text-slate-500"}`}>List</button><button type="button" onClick={() => setView("Kalender")} className={`rounded px-3 py-1.5 ${view === "Kalender" ? "bg-slate-700" : "text-slate-500"}`}>Kalender</button></div></div>{isLoading ? <div className="grid min-h-52 place-items-center text-sm text-slate-500">Memuat jadwal…</div> : shown.length === 0 ? <div className="grid min-h-64 place-items-center text-center"><div><CalendarDays className="mx-auto rounded-xl bg-slate-800 p-3 text-slate-400" size={42} /><p className="mt-4 text-sm font-bold">Tidak ada jadwal yang cocok</p><p className="mt-2 text-xs text-slate-500">Coba ganti filter atau cari dengan kata lain.</p></div></div> : <div className="divide-y divide-slate-800">{shown.map((booking) => <div key={booking.id} className="flex items-center justify-between p-4 text-sm"><span>{booking.customer_name}</span><span className="text-slate-400">{booking.start_date} — {booking.end_date}</span></div>)}</div>}</section>;
}

function Schedules({ selectedProductId }: { selectedProductId: string | null }) {
    const queryClient = useQueryClient();
    const { data: products = [] } = useQuery({ queryKey: ["admin-products"], queryFn: fetchAllProducts });
    const { data: bookings = [], isLoading } = useQuery({ queryKey: ["bookings"], queryFn: async () => { const { data, error } = await supabase.from("bookings").select("*").order("created_at", { ascending: false }); if (error) throw error; return data; } });
    const { data: bookingItems = [] } = useQuery({ queryKey: ["booking-items"], queryFn: async () => { const { data, error } = await supabase.from("booking_items").select("*"); if (error) throw error; return data; } });
    const [search, setSearch] = useState("");
    const [period, setPeriod] = useState("Semua");
    const [view, setView] = useState<"List" | "Kalender">("List");
    const [productId, setProductId] = useState(selectedProductId ?? "");
    const [month, setMonth] = useState(() => new Date());
    const [adding, setAdding] = useState(false);

    useEffect(() => setProductId(selectedProductId ?? ""), [selectedProductId]);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const sevenDaysFromNow = new Date(today);
    sevenDaysFromNow.setDate(today.getDate() + 6);
    const dateFromBooking = (value: string) => new Date(`${value}T00:00:00`);
    const selectPeriod = (nextPeriod: string) => {
        setPeriod(nextPeriod);
        if (nextPeriod === "Hari ini" || nextPeriod === "7 hari") setMonth(new Date(today.getFullYear(), today.getMonth(), 1));
    };
    const shown = bookings.filter((booking) => {
        const matchesSearch = booking.customer_name.toLowerCase().includes(search.toLowerCase()) || booking.customer_whatsapp.includes(search);
        const matchesProduct = !productId || bookingItems.some((item) => item.booking_id === booking.id && item.product_id === productId);
        const startDate = dateFromBooking(booking.start_date);
        const endDate = dateFromBooking(booking.end_date);
        const matchesPeriod = period === "Semua"
            || (period === "Hari ini" && startDate <= today && endDate >= today)
            || (period === "7 hari" && startDate <= sevenDaysFromNow && endDate >= today)
            || (period === "Terlambat" && endDate < today && booking.status !== "completed" && booking.status !== "cancelled");
        return matchesSearch && matchesProduct && matchesPeriod;
    });

    return <><section className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/20"><div className="border-b border-slate-800 p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="font-bold">Jadwal Sewa</h2><p className="mt-1 text-xs text-slate-400">Catat booking supaya tanggalnya otomatis tertutup di katalog.</p></div><button type="button" onClick={() => setAdding(true)} className="rounded-lg bg-blue-500 px-4 py-2 text-xs font-bold"><Plus size={14} className="mr-1 inline" /> Tambah jadwal</button></div></div><div className="border-b border-slate-800 px-5 py-4"><div className="flex flex-wrap items-center gap-2"><span className="mr-1 text-xs text-slate-500">Waktu:</span>{["Semua", "Hari ini", "7 hari", "Terlambat"].map((item) => <button key={item} type="button" onClick={() => selectPeriod(item)} className={`rounded-full px-3 py-2 text-[.65rem] font-bold ${period === item ? "bg-slate-700 text-white" : "border border-slate-800 text-slate-400"}`}>{item}</button>)}</div></div><div className="flex flex-wrap gap-2 border-b border-slate-800 p-4"><input className="h-10 min-w-44 flex-1 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs outline-none focus:border-blue-400" placeholder="Cari barang, customer, atau WA..." value={search} onChange={(event) => setSearch(event.target.value)} /><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs" value={productId} onChange={(event) => setProductId(event.target.value)}><option value="">Semua barang</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs"><option>Semua SKU</option></select><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs"><option>Status aktif</option><option>Pending</option><option>Terkonfirmasi</option></select><select className="h-10 rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs"><option>Terakhir dibuat</option></select><div className="flex rounded-lg border border-slate-800 p-1 text-xs"><button type="button" onClick={() => setView("List")} className={`rounded px-3 py-1.5 ${view === "List" ? "bg-slate-700 text-white" : "text-slate-500"}`}>List</button><button type="button" onClick={() => setView("Kalender")} className={`rounded px-3 py-1.5 ${view === "Kalender" ? "bg-slate-700 text-white" : "text-slate-500"}`}>Kalender</button></div></div>{isLoading ? <div className="grid min-h-52 place-items-center text-sm text-slate-500">Memuat jadwalâ€¦</div> : view === "Kalender" ? <ScheduleCalendar month={month} bookings={shown} onPrevious={() => setMonth((current) => new Date(current.getFullYear(), current.getMonth() - 1, 1))} onNext={() => setMonth((current) => new Date(current.getFullYear(), current.getMonth() + 1, 1))} /> : shown.length === 0 ? <div className="grid min-h-64 place-items-center text-center"><div><CalendarDays className="mx-auto rounded-xl bg-slate-800 p-3 text-slate-400" size={42} /><p className="mt-4 text-sm font-bold">Tidak ada jadwal yang cocok</p><p className="mt-2 text-xs text-slate-500">Coba ganti filter atau cari dengan kata lain.</p></div></div> : <div className="divide-y divide-slate-800">{shown.map((booking) => <div key={booking.id} className="flex items-center justify-between p-4 text-sm"><span>{booking.customer_name}</span><span className="text-slate-400">{booking.start_date} â€” {booking.end_date}</span></div>)}</div>}</section>{adding && <AddScheduleModal products={products} defaultProductId={selectedProductId} onClose={() => setAdding(false)} onSaved={() => { queryClient.invalidateQueries({ queryKey: ["bookings"] }); queryClient.invalidateQueries({ queryKey: ["booking-items"] }); setAdding(false); }} />}</>;
}

function ScheduleCalendar({ month, bookings, onPrevious, onNext }: { month: Date; bookings: { id: string; customer_name: string; start_date: string; end_date: string }[]; onPrevious: () => void; onNext: () => void }) {
    const year = month.getFullYear(); const monthIndex = month.getMonth();
    const firstDay = new Date(year, monthIndex, 1); const leadingDays = (firstDay.getDay() + 6) % 7;
    const gridStart = new Date(year, monthIndex, 1 - leadingDays);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const calendarDays = Array.from({ length: 42 }, (_, index) => new Date(gridStart.getFullYear(), gridStart.getMonth(), gridStart.getDate() + index));
    const asLocalDate = (value: string) => new Date(`${value}T00:00:00`);
    return <div className="p-4"><section className="overflow-hidden rounded-xl border border-slate-800"><div className="flex items-center justify-between border-b border-slate-800 px-4 py-3"><h3 className="text-sm font-bold capitalize">{new Intl.DateTimeFormat("id-ID", { month: "long", year: "numeric" }).format(month)}</h3><div className="flex gap-2"><button type="button" onClick={onPrevious} aria-label="Bulan sebelumnya" className="rounded-lg border border-slate-800 p-1.5 text-slate-400 hover:border-blue-400 hover:text-white"><ChevronLeft size={15} /></button><button type="button" onClick={onNext} aria-label="Bulan berikutnya" className="rounded-lg border border-slate-800 p-1.5 text-slate-400 hover:border-blue-400 hover:text-white"><ChevronRight size={15} /></button></div></div><div className="grid grid-cols-7 border-b border-slate-800 bg-slate-950/30">{["Sen", "Sel", "Rab", "Kam", "Jum", "Sab", "Min"].map((day) => <div key={day} className="py-2 text-center text-[0.58rem] font-bold uppercase text-slate-500">{day}</div>)}</div><div className="grid grid-cols-7">{calendarDays.map((day) => { const inMonth = day.getMonth() === monthIndex; const isToday = day.getTime() === today.getTime(); const dayBookings = bookings.filter((booking) => { const start = asLocalDate(booking.start_date); const end = asLocalDate(booking.end_date); return day >= start && day <= end; }); return <div key={day.toISOString()} className={`min-h-24 border-b border-r border-slate-800 p-2 last:border-r-0 sm:min-h-28 ${inMonth ? "bg-[#0b0d12]" : "bg-slate-900/50 text-slate-600"}`}><span className={`grid h-5 w-5 place-items-center rounded-full text-[0.65rem] font-bold ${isToday ? "bg-blue-500 text-white" : ""}`}>{day.getDate()}</span><div className="mt-1 space-y-1">{dayBookings.slice(0, 2).map((booking) => <div key={booking.id} className="truncate rounded bg-blue-500/20 px-1.5 py-1 text-[0.58rem] font-semibold text-blue-200" title={booking.customer_name}>{booking.customer_name}</div>)}{dayBookings.length > 2 && <p className="text-[0.58rem] text-slate-400">+{dayBookings.length - 2} booking</p>}</div></div>; })}</div></section></div>;
}

function AddScheduleModal({ products, defaultProductId, onClose, onSaved }: { products: Product[]; defaultProductId: string | null; onClose: () => void; onSaved: () => void }) {
    const [productId, setProductId] = useState(defaultProductId ?? "");
    const [startDate, setStartDate] = useState("");
    const [endDate, setEndDate] = useState("");
    const [appointmentDate, setAppointmentDate] = useState("");
    const [datePicker, setDatePicker] = useState<"rental" | "appointment" | null>(null);
    const [customerName, setCustomerName] = useState("");
    const [customerWhatsapp, setCustomerWhatsapp] = useState("");
    const [error, setError] = useState("");
    const [saving, setSaving] = useState(false);
    const selectedProduct = products.find((product) => product.id === productId);
    const canSave = Boolean(selectedProduct && startDate && endDate && endDate >= startDate && customerName.trim() && customerWhatsapp.trim());
    async function save(event: React.FormEvent) {
        event.preventDefault(); if (saving) return; setError("");
        if (!canSave) { setError("Lengkapi tanggal sewa, barang, serta data customer."); return; }
        if (endDate < startDate) { setError("Tanggal kembali harus setelah tanggal sewa."); return; }
        setSaving(true);
        const notes = appointmentDate ? `Tanggal appointment: ${appointmentDate}` : null;
        const { data: booking, error: bookingError } = await supabase.from("bookings").insert({ customer_name: customerName, customer_whatsapp: customerWhatsapp, start_date: startDate, end_date: endDate, notes }).select("id").single();
        if (bookingError || !booking) { setError(bookingError?.message ?? "Jadwal tidak dapat disimpan."); setSaving(false); return; }
        const { error: itemError } = await supabase.from("booking_items").insert({ booking_id: booking.id, product_id: productId, price: Number(selectedProduct?.price ?? 0) });
        if (itemError) { setError(itemError.message); setSaving(false); return; }
        onSaved();
    }
    return <div className="fixed inset-0 z-50 grid place-items-center bg-black/75 p-4 backdrop-blur-sm"><form onSubmit={save} className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-xl border border-slate-700 bg-[#0d1016] shadow-2xl"><header className="flex items-start justify-between border-b border-slate-800 px-5 py-4"><div><h2 className="text-sm font-bold">Catat jadwal baru</h2><p className="mt-1 text-[0.65rem] text-slate-400">Kalau tanggal bertabrakan dengan booking aktif, sistem akan menolak.</p></div><button type="button" onClick={onClose} aria-label="Tutup" className="rounded-md border border-slate-700 p-1.5 text-slate-400 hover:text-white"><X size={14} /></button></header><div className="space-y-4 p-5"><div className="relative"><p className="text-[0.65rem] font-bold uppercase tracking-wide text-slate-400">Tanggal sewa</p><button type="button" onClick={() => setDatePicker(datePicker === "rental" ? null : "rental")} className="mt-2 flex h-10 w-full items-center gap-2 rounded-md border border-slate-700 bg-[#0b0d12] px-3 text-left text-xs"><CalendarDays size={14} className="text-blue-400" /><span>{startDate ? `${formatScheduleDate(startDate)}${endDate ? ` — ${formatScheduleDate(endDate)}` : " · pilih tanggal kembali"}` : "Pilih tanggal sewa"}</span><ChevronDown size={14} className="ml-auto text-slate-500" /></button>{datePicker === "rental" && <ScheduleDatePicker range startDate={startDate} endDate={endDate} onSelect={(value) => { if (!startDate || endDate || value < startDate) { setStartDate(value); setEndDate(""); } else { setEndDate(value); setDatePicker(null); } }} />}</div><label className="block text-[0.65rem] font-bold uppercase tracking-wide text-slate-400">Barang disewa<select required className="mt-2 h-10 w-full rounded-md border border-slate-700 bg-[#0b0d12] px-3 text-xs text-white" value={productId} onChange={(event) => setProductId(event.target.value)}><option value="">Pilih barang atau SKU...</option>{products.filter((product) => product.status).map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select><span className="mt-1 block normal-case font-normal text-slate-500">Pilih barang yang akan ditutup pada kalender.</span></label><div className="relative"><p className="text-[0.65rem] font-bold uppercase tracking-wide text-slate-400">Tanggal appointment (opsional)</p><button type="button" onClick={() => setDatePicker(datePicker === "appointment" ? null : "appointment")} className="mt-2 flex h-10 w-full items-center gap-2 rounded-md border border-slate-700 bg-[#0b0d12] px-3 text-left text-xs"><CalendarDays size={14} className="text-blue-400" /><span>{appointmentDate ? formatScheduleDate(appointmentDate) : "Belum ditentukan"}</span><ChevronDown size={14} className="ml-auto text-slate-500" /></button>{datePicker === "appointment" && <ScheduleDatePicker startDate={appointmentDate} endDate="" onSelect={(value) => { setAppointmentDate(value); setDatePicker(null); }} />}</div><div className="grid gap-3 sm:grid-cols-2"><label className="block text-[0.65rem] font-bold uppercase tracking-wide text-slate-400">Nama customer<input required className="mt-2 h-10 w-full rounded-md border border-slate-700 bg-[#0b0d12] px-3 text-xs text-white" placeholder="Contoh: Alya Resti" value={customerName} onChange={(event) => setCustomerName(event.target.value)} /></label><label className="block text-[0.65rem] font-bold uppercase tracking-wide text-slate-400">WhatsApp customer<input required className="mt-2 h-10 w-full rounded-md border border-slate-700 bg-[#0b0d12] px-3 text-xs text-white" placeholder="Contoh: 628xxxx" value={customerWhatsapp} onChange={(event) => setCustomerWhatsapp(event.target.value)} /></label></div>{error && <p className="text-xs text-rose-400">{error}</p>}<div className="flex justify-end border-t border-slate-800 pt-4"><button disabled={!canSave || saving} className={`rounded-lg px-4 py-2 text-xs font-bold text-white transition-colors disabled:cursor-not-allowed ${canSave && !saving ? "bg-emerald-600 hover:bg-emerald-500" : "bg-slate-600"}`}>{saving ? "Menyimpan..." : "Simpan jadwal"}</button></div></div></form></div>;
}

function formatScheduleDate(value: string) {
    return new Intl.DateTimeFormat("id-ID", { day: "numeric", month: "short", year: "numeric" }).format(new Date(`${value}T00:00:00`));
}

function ScheduleDatePicker({ startDate, endDate, onSelect, range = false }: { startDate: string; endDate: string; onSelect: (date: string) => void; range?: boolean }) {
    const from = startDate ? new Date(`${startDate}T00:00:00`) : undefined;
    const to = endDate ? new Date(`${endDate}T00:00:00`) : undefined;
    const selectDay = (date: Date) => onSelect(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`);
    const common = {
        locale: calendarLocale,
        weekStartsOn: 1 as const,
        defaultMonth: from ?? new Date(),
        captionLayout: "dropdown" as const,
        startMonth: new Date(2020, 0),
        endMonth: new Date(new Date().getFullYear() + 10, 11),
        className: "rounded-lg bg-transparent text-slate-100",
        autoFocus: true,
    };
    return <div className="dark relative z-20 mt-2 w-fit max-w-full rounded-lg border border-slate-700 bg-[#11151d] shadow-2xl">
        {range ? <Calendar {...common} mode="range" selected={{ from, to }} onDayClick={selectDay} /> : <Calendar {...common} mode="single" selected={from} onSelect={(date) => { if (date) selectDay(date); }} />}
        <p className="px-3 pb-3 text-xs text-slate-400">{range ? (from && !to ? "Pilih tanggal kembali." : "Pilih tanggal mulai dan kembali.") : "Pilih tanggal appointment."}</p>
    </div>;
}
function StoreSettings() {
    const queryClient = useQueryClient();
    const { data: settings } = useQuery({ queryKey: ["settings"], queryFn: fetchSettings });
    const [form, setForm] = useState({ business_name: "", logo_url: "", catalog_slug: "sancea", store_address: "", maps_url: "", tagline: "", instagram: "", tiktok: "", whatsapp_number: "", minimum_rental_days: 3, show_rental_dates: true, catalog_visible: true, social_link_style: "pill", store_name_font: "Playball", default_product_order: "newest", catalog_appearance: defaultAppearance });
    const [notice, setNotice] = useState("");
    const [logoBusy, setLogoBusy] = useState(false);
    const [logoError, setLogoError] = useState("");
    async function uploadLogo(file: File | undefined) {
        if (!file) return;
        setLogoError("");
        if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 5 * 1024 * 1024) {
            setLogoError("Pilih PNG, JPG, atau WebP maksimal 5 MB."); return;
        }
        setLogoBusy(true);
        try {
            const logo_url = await uploadProductImage(file);
            setForm(current => ({ ...current, logo_url }));
        } catch (error) {
            setLogoError(error instanceof Error ? error.message : "Upload logo gagal. Silakan coba lagi.");
        } finally { setLogoBusy(false); }
    }
    useEffect(() => { if (settings) setForm({ business_name: settings.business_name, logo_url: settings.logo_url ?? "", catalog_slug: settings.catalog_slug, store_address: settings.store_address ?? "", maps_url: settings.maps_url ?? "", tagline: settings.tagline ?? "", instagram: settings.instagram ?? "", tiktok: settings.tiktok ?? "", whatsapp_number: settings.whatsapp_number, minimum_rental_days: settings.minimum_rental_days, show_rental_dates: settings.show_rental_dates, catalog_visible: settings.catalog_visible, social_link_style: settings.social_link_style, store_name_font: settings.store_name_font, default_product_order: settings.default_product_order, catalog_appearance: { ...defaultAppearance, ...settings.catalog_appearance } }); }, [settings]);
    const update = (name: keyof typeof form, value: string | number | boolean) => setForm((current) => ({ ...current, [name]: value }));
    async function save(event: React.FormEvent) { event.preventDefault(); if (!settings || logoBusy) return; const { error } = await supabase.from("settings").update(form).eq("id", settings.id); setNotice(error ? error.message : "Pengaturan tersimpan."); if (!error) queryClient.invalidateQueries({ queryKey: ["settings"] }); }
    return <form onSubmit={save} className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_24rem] xl:items-start"><section className="overflow-hidden rounded-2xl border border-slate-800"><div className="border-b border-slate-800 p-6"><h2 className="font-bold">Informasi toko</h2><p className="mt-1 text-sm text-slate-500">Nama, kontak, link sosial, dan tampilan katalog.</p><button disabled={logoBusy} className="disabled:opacity-50 mt-5 h-11 bg-amber-400 px-5 text-sm font-bold text-slate-950">Simpan pengaturan</button>{notice && <p className="mt-3 text-sm text-slate-400">{notice}</p>}</div><SettingsBlock title="Identitas"><Field label="Nama toko"><input className={inputClass} value={form.business_name} onChange={(e) => update("business_name", e.target.value)} required /></Field><Field label="Alamat katalog"><div className="mt-2 flex h-11 items-center border border-slate-700 bg-slate-950 px-3 text-sm"><span className="text-slate-500">/</span><input className="ml-3 w-full bg-transparent outline-none" value={form.catalog_slug} onChange={(e) => update("catalog_slug", e.target.value)} /></div></Field></SettingsBlock><SettingsBlock title="Tampilan & gaya kustom"><Field label="Font nama toko"><select className={inputClass} value={form.store_name_font} onChange={(e) => update("store_name_font", e.target.value)}>{storeFontGroups.map(group => <optgroup key={group.label} label={group.label}>{group.names.map(name => <option key={name} value={name}>{name}</option>)}</optgroup>)}</select></Field><p className="mt-5 text-xs font-semibold uppercase tracking-[0.12em] text-slate-400">Gaya link sosial media</p><div className="mt-2 grid grid-cols-2 rounded-lg border border-slate-700 p-1 text-sm"><button type="button" onClick={() => update("social_link_style", "pill")} className={`rounded-md py-2 ${form.social_link_style === "pill" ? "bg-slate-800 text-white" : "text-slate-500"}`}>Tombol pil</button><button type="button" onClick={() => update("social_link_style", "icon")} className={`rounded-md py-2 ${form.social_link_style === "icon" ? "bg-slate-800 text-white" : "text-slate-500"}`}>Hanya ikon</button></div><div className="mt-5"><p className="text-sm text-slate-200">Logo toko (opsional)</p>{form.logo_url && <div className="mt-3 flex items-center gap-4"><StorageImage path={form.logo_url} alt="Logo toko" className="h-20 w-32 rounded-lg bg-white/10 object-contain p-2" /><button type="button" disabled={logoBusy} onClick={() => { update("logo_url", ""); setLogoError(""); }} className="rounded-lg border border-rose-400/30 px-3 py-2 text-xs text-rose-300">Hapus logo</button></div>}<FileUploadButton className="mt-3" accept="image/png,image/jpeg,image/webp" disabled={logoBusy} onChange={event => { void uploadLogo(event.target.files?.[0]); event.target.value = ""; }} /><p aria-live="polite" className="mt-2 text-xs text-slate-400">{logoBusy ? "Mengupload logo..." : "PNG, JPG, atau WebP, maksimal 5 MB. Simpan pengaturan untuk menerapkan logo."}</p>{logoError && <p role="alert" className="mt-2 text-xs text-rose-400">{logoError}</p>}</div><Field label="Lokasi / alamat toko"><input className={inputClass} value={form.store_address} onChange={(e) => update("store_address", e.target.value)} /></Field><Field label="Link lokasi Maps (opsional)"><input className={inputClass} value={form.maps_url} onChange={(e) => update("maps_url", e.target.value)} /></Field><Field label="Tagline toko"><input className={inputClass} value={form.tagline} onChange={(e) => update("tagline", e.target.value)} placeholder="Contoh: Kebaya pilihan untuk momen istimewa." /></Field></SettingsBlock><SettingsBlock title="Kontak & sosial"><Field label="Instagram (kosongkan untuk menyembunyikan)"><input placeholder="@namaakun" className={inputClass} value={form.instagram} onChange={(e) => update("instagram", e.target.value)} /></Field><Field label="TikTok"><input className={inputClass} value={form.tiktok} onChange={(e) => update("tiktok", e.target.value)} /></Field><Field label="WhatsApp"><input className={inputClass} value={form.whatsapp_number} onChange={(e) => update("whatsapp_number", e.target.value)} required /></Field></SettingsBlock><SettingsBlock title="Pengaturan sewa"><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={form.show_rental_dates} onChange={(e) => update("show_rental_dates", e.target.checked)} /> Tampilkan pilihan tanggal di katalog</label><Field label="Min. sewa (hari)"><input className={inputClass} type="number" min="1" value={form.minimum_rental_days} onChange={(e) => update("minimum_rental_days", Number(e.target.value))} /></Field></SettingsBlock><SettingsBlock title="Status katalog"><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={form.catalog_visible} onChange={(e) => update("catalog_visible", e.target.checked)} /> <span className={form.catalog_visible ? "text-emerald-400" : "text-slate-500"}>{form.catalog_visible ? "● Tayang untuk customer" : "● Disembunyikan"}</span></label><Field label="Urutan default barang"><select className={inputClass} value={form.default_product_order} onChange={(e) => update("default_product_order", e.target.value)}><option value="newest">Produk terbaru</option><option value="price_low">Harga terendah</option><option value="price_high">Harga tertinggi</option></select></Field></SettingsBlock></section><StorePreview form={form} onAppearanceChange={(catalog_appearance) => setForm(current => ({ ...current, catalog_appearance }))} /></form>;
}

function SettingsBlock({ title, children }: { title: string; children: React.ReactNode }) { return <fieldset className="border-b border-slate-800 p-6 last:border-0"><legend className="text-xs font-bold uppercase tracking-[0.14em] text-slate-500">{title}</legend>{children}</fieldset>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) {
    if (label === "Override harga") {
        return <OverrideSkuPrice>{children}</OverrideSkuPrice>;
    }
    return <label className="mt-5 block text-sm text-slate-200">{label}{children}</label>;
}

function OverrideSkuPrice({ children: _children }: { children: React.ReactNode }) {
    const [enabled, setEnabled] = useState(false);
    const [prices, setPrices] = useState([{ duration: "1", price: "" }]);
    const updatePrice = (index: number, key: "duration" | "price", value: string) => setPrices((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item));
    const addPrice = () => setPrices((current) => [...current, { duration: String((Number(current.at(-1)?.duration) || 0) + 1), price: "" }]);
    const removePrice = (index: number) => setPrices((current) => current.length === 1 ? current : current.filter((_, itemIndex) => itemIndex !== index));
    return <div className="mt-5 rounded-xl border border-slate-800 bg-slate-950/30 p-4 text-sm text-slate-200"><label className="flex cursor-pointer items-start gap-3"><input type="checkbox" className="mt-1 h-4 w-4 accent-blue-500" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} /><span><b>Gunakan harga khusus untuk SKU ini</b><span className="mt-1 block text-xs leading-5 text-slate-500">Jika tidak dicentang, SKU mengikuti harga produk induk.</span></span></label>{enabled && <div className="mt-5 overflow-hidden rounded-xl border border-slate-800 bg-[#0d1119]"><div className="border-b border-slate-800 px-4 py-4"><b className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-amber-400/15 text-amber-400">⌑</span> Harga berdasarkan durasi</b><p className="mt-2 text-xs leading-5 text-slate-500">Tambahkan harga khusus SKU untuk satu hari, dua hari, dan durasi lainnya.</p></div><div className="p-4"><div className="rounded-lg border border-slate-800 bg-[#0b0d12] p-3"><div className="mb-3 grid grid-cols-[5.5rem_minmax(0,1fr)_2rem] gap-3 text-[0.58rem] font-bold uppercase tracking-[0.12em] text-slate-500"><span>Durasi</span><span>Harga paket</span><span /></div>{prices.map((item, index) => <div key={index} className="mb-3 grid grid-cols-[5.5rem_minmax(0,1fr)_2rem] items-center gap-3"><div className="relative"><RupiahInput className="h-10 w-full rounded-lg border border-slate-700 bg-slate-950 px-3 pr-9 text-sm outline-none focus:border-blue-400" min="1" value={item.duration} onValueChange={(value) => updatePrice(index, "duration", value)} /><span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[0.62rem] text-slate-500">hari</span></div><div className="flex h-10 items-center rounded-lg border border-slate-700 bg-slate-950 focus-within:border-blue-400"><span className="px-3 text-xs font-semibold text-slate-500">Rp</span><RupiahInput className="min-w-0 flex-1 bg-transparent pr-3 text-sm outline-none" value={item.price} onValueChange={(value) => updatePrice(index, "price", value)} /></div><button type="button" onClick={() => removePrice(index)} className="grid h-9 w-9 place-items-center rounded-lg text-slate-500 transition hover:bg-rose-500/10 hover:text-rose-400" aria-label="Hapus harga"><Trash2 size={15} /></button></div>)}<button type="button" onClick={addPrice} className="mt-1 flex h-10 w-full items-center justify-center gap-2 rounded-lg border border-slate-700 text-xs font-bold transition hover:border-blue-400 hover:text-blue-300"><Plus size={14} /> Tambah list harga</button></div><Field label="Biaya tambahan per hari (opsional)"><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs text-slate-500">Rp</span><RupiahInput className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950 pl-9 pr-3 text-sm outline-none focus:border-blue-400" placeholder="Contoh: 200.000" /></div></Field></div></div>}</div>;
}
function StorePreview({ form, onAppearanceChange }: { onAppearanceChange: (value: Appearance) => void; form: { logo_url: string; catalog_slug: string; business_name: string; tagline: string; catalog_appearance: Appearance; catalog_visible: boolean; instagram: string; store_name_font: string; social_link_style: string; store_address: string; maps_url: string; whatsapp_number: string } }) {
    const [version, setVersion] = useState(0);
    const previewUrl = `/katalog?store_name=${encodeURIComponent(form.business_name)}&tagline=${encodeURIComponent(form.tagline)}&visible=${form.catalog_visible}&instagram=${encodeURIComponent(form.instagram)}&store_name_font=${encodeURIComponent(form.store_name_font)}&social_link_style=${form.social_link_style}&store_address=${encodeURIComponent(form.store_address)}&maps_url=${encodeURIComponent(form.maps_url)}&whatsapp_number=${encodeURIComponent(form.whatsapp_number)}&appearance=${encodeURIComponent(JSON.stringify(form.catalog_appearance))}&logo_url=${encodeURIComponent(form.logo_url)}&preview=${version}`;
    return (
        <aside className="sticky top-5">
            <AppearanceEditor value={form.catalog_appearance} onChange={onAppearanceChange} />
            <div className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-950">
                <div className="flex items-center justify-between border-b border-slate-800 p-4">
                    <div>
                        <p className="font-bold">Preview toko</p>
                        <p className="text-xs text-slate-500">{form.business_name || "Sancea Kebaya"}</p>
                    </div>
                    <div className="flex items-center gap-3">
                        <button type="button" onClick={() => setVersion((current) => current + 1)} className="rounded-lg border border-slate-800 p-2 text-slate-400 transition hover:border-amber-400 hover:text-white" aria-label="Muat ulang preview">↻</button>
                        <a href="/katalog?from=admin" target="_blank" rel="noreferrer" aria-label="Buka katalog di tab baru" className="rounded-lg border border-slate-800 p-2 text-slate-400 transition hover:border-amber-400 hover:text-white"><ExternalLink size={16} /></a>
                    </div>
                </div>
                <div className="mx-auto h-[42rem] max-w-[25rem] bg-white">
                    <iframe title={`Preview katalog ${form.catalog_slug || "sancea"}`} src={previewUrl} className="h-full w-full border-0" />
                </div>
            </div>
        </aside>
    );
}

function Nav({ icon: Icon, label, active, onClick }: { icon: typeof Box; label: string; active: boolean; onClick: () => void }) { return <button type="button" onClick={onClick} className={`flex items-center gap-3 rounded-xl px-4 py-3 text-left text-sm font-semibold transition ${active ? "bg-slate-800 text-white" : "text-slate-400 hover:bg-slate-900 hover:text-white"}`}><Icon size={17} />{label}</button>; }
